import React, { useState, useEffect } from "react";
import axios from "axios";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  CircularProgress,
} from "@mui/material";

const ProfessorAvaliacoes = ({ professorId }) => {
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchAvaliacoes = async () => {
      try {
        const response = await axios.get(
          `http://localhost:3001/professores/${professorId}/avaliacoes`
        );
        setAvaliacoes(response.data);
        setLoading(false);
      } catch (err) {
        setError("Erro ao carregar avaliações.");
        setLoading(false);
      }
    };

    fetchAvaliacoes();
  }, [professorId]);

  if (loading) return <CircularProgress />;
  if (error) return <Typography color="error">{error}</Typography>;

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Avaliações e Submissões
      </Typography>

      {avaliacoes.map((avaliacao) => (
        <Paper
          key={avaliacao.id}
          style={{ marginBottom: "20px", padding: "16px" }}
        >
          <Typography variant="h5">
            {avaliacao.titulo} (Curso: {avaliacao.Curso?.nome || "N/A"})
          </Typography>

          <Typography variant="subtitle1">
            Período: {new Date(avaliacao.dataInicio).toLocaleDateString()} até{" "}
            {new Date(avaliacao.dataFim).toLocaleDateString()}
          </Typography>

          <TableContainer component={Paper} style={{ marginTop: "10px" }}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Aluno</TableCell>
                  <TableCell>Pontuação</TableCell>
                  <TableCell>Tempo Gasto</TableCell>
                  <TableCell>Data de Submissão</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {avaliacao.submissoes?.length > 0 ? (
                  avaliacao.submissoes.map((submissao) => (
                    <TableRow key={submissao.id}>
                      <TableCell>{submissao.nomeAluno}</TableCell>
                      <TableCell>
                        {submissao.pontuacao} / {avaliacao.pontuacaoMaxima}
                      </TableCell>
                      <TableCell>{submissao.tempo}</TableCell>
                      <TableCell>{submissao.entregue}</TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={4} align="center">
                      Nenhuma submissão encontrada.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      ))}
    </div>
  );
};

export default ProfessorAvaliacoes;
